import React, { useState, useEffect } from 'react';
import { useParams, useNavigate, Link } from 'react-router-dom';
import { MapPin, Clock, Share2, MessageCircle, ChevronRight, CheckCircle, Eye, AlertCircle, Phone } from 'lucide-react';

import ChatWidget from '../components/ChatWidget';
import toast from 'react-hot-toast';
import { useAuth } from '../context/AuthContext';
import { formatPriceShortVND } from '../utils/valuationHelpers';

const PublicCarDetail = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const { user } = useAuth();
  const [car, setCar] = useState(null);
  const [activeImage, setActiveImage] = useState(0);
  const [commentInput, setCommentInput] = useState('');
  const [comments, setComments] = useState([]);

  const [showContactModal, setShowContactModal] = useState(false);
  const [contactMessage, setContactMessage] = useState('');

  const handleImageError = (e) => {
    e.target.onerror = null; // prevent infinite loop
    e.target.src = "data:image/svg+xml;charset=utf-8,%3Csvg xmlns='http://www.w3.org/2000/svg' width='800' height='600' fill='%23f8fbff'%3E%3Crect width='800' height='600'/%3E%3Ctext x='50%25' y='50%25' dominant-baseline='middle' text-anchor='middle' font-family='sans-serif' font-size='24' fill='%239ca3af'%3EKh%C3%B4ng t%C3%ACm th%E1%BA%A5y %E1%BA%A3nh%3C/text%3E%3C/svg%3E";
  };

  useEffect(() => {
    const fetchCar = async () => {
      try {
        const { getPublicListingById } = await import('../services/carListingService');
        const data = await getPublicListingById(id);

        if (data) {
          const mapped = {
            ...data,
            id: data._id,
            title: `${data.brand} ${data.model} ${data.year}`,
            highestBid: data.price ? `${(data.price / 1000000).toLocaleString()} Tr` : 'Thỏa thuận',
            location: data.location || 'Hà Nội',
            mileage: `${data.mileage.toLocaleString()} km`,
            // Giả lập danh sách ảnh nếu chỉ có 1 ảnh chính
            images: data.images?.length > 0 ? data.images : [data.image || 'https://images.unsplash.com/photo-1550355291-bbee04a92027'],
            user: 'Store Car'
          };
          setCar(mapped);
        }
      } catch (err) {
        toast.error('Không tìm thấy thông tin xe');
        setCar(null);
      }
    };
    fetchCar();

    // Load comments for this car from localStorage
    const storedComments = JSON.parse(localStorage.getItem(`storeCar_comments_${id}`)) || [
      { id: 1, author: '*****5786', text: 'Xe còn trong tình trạng tốt không, tôi có thể đến xem trực tiếp không?', time: 'khoảng 1 giờ trước' },
      { id: 2, author: '*****1201', text: 'Cho hỏi xe có hỗ trợ trả góp không ạ?', time: 'hôm qua' }
    ];
    setComments(storedComments);
  }, [id]);

  const handleSendComment = () => {
    if (!commentInput.trim()) return;
    const newComment = {
      id: Date.now(),
      author: `*****${Math.floor(1000 + Math.random() * 9000)}`,
      text: commentInput.trim(),
      time: 'Vừa xong'
    };
    const updated = [newComment, ...comments];
    setComments(updated);
    localStorage.setItem(`storeCar_comments_${id}`, JSON.stringify(updated));
    setCommentInput('');
    toast.success('Đã gửi câu hỏi!');
  };

  const handleContactClick = () => {
    if (!user) {
      toast.error('Vui lòng đăng nhập để liên hệ người bán!');
      navigate('/login');
      return;
    }
    setShowContactModal(true);
  };

  const submitContactRequest = () => {
    if (!contactMessage.trim()) {
      toast.error('Vui lòng nhập tin nhắn!');
      return;
    }

    const newRequest = {
      id: Date.now(),
      carId: car.id || car._id || 'unknown',
      carTitle: car.title || `${car.brand || ''} ${car.model || ''}`.trim() || 'Xe không xác định',
      customerId: user._id || 'guest',
      customerName: user.name || 'Khách hàng',
      customerPhone: user.phone || 'Chưa cập nhật',
      message: contactMessage,
      status: 'pending',
      createdAt: new Date().toISOString(),
      carPrice: car.highestBid || car.price || 'Thỏa thuận'
    };

    const existingRequests = JSON.parse(localStorage.getItem('storeCar_buy_requests')) || [];
    localStorage.setItem('storeCar_buy_requests', JSON.stringify([newRequest, ...existingRequests]));

    toast.success('Yêu cầu liên hệ đã được gửi đến hệ thống!');
    setShowContactModal(false);
    setContactMessage('');
  };

  if (!car) {
    return (
      <div className="min-h-screen bg-[#f3f7f9] flex flex-col items-center justify-center">
         <AlertCircle size={48} className="text-gray-400 mb-4" />
         <h2 className="text-xl font-bold text-gray-700">Không tìm thấy xe</h2>
         <button onClick={() => navigate('/buy-car')} className="mt-4 text-[#0096ff] font-bold hover:underline">
           Quay lại trang danh sách
         </button>
      </div>
    );
  }

  // Derive some fake data since mock/local might not have deep specs
  // Split title to get brand (e.g. "Toyota Camry 2020" -> "Toyota")
  const brandName = car.title?.split(' ')[0] || 'Unknown';
  const year = car.title?.match(/\d{4}/)?.[0] || '2020';
  const odo = car.mileage || 'Chưa cập nhật';
  const location = car.location || 'Chưa cập nhật';

  // Chỉ hiển thị ảnh thực tế của xe (do người dùng upload)
  const images = Array.isArray(car.images) && car.images.length > 0
    ? car.images
    : car.image
      ? [car.image]
      : [];


  return (
    <div className="min-h-screen bg-[#f3f7f9] pt-6 pb-20">
      <div className="max-w-[1280px] mx-auto px-4 xl:px-0">

        {/* Breadcrumb */}
        <div className="flex items-center text-sm text-gray-500 mb-4 gap-2">
          <Link to="/" className="hover:text-blue-500">Trang chủ</Link>
          <ChevronRight size={14} />
          <Link to="/buy-car" className="hover:text-blue-500">Mua xe</Link>
          <ChevronRight size={14} />
          <span className="text-gray-800 font-semibold">{brandName}</span>
        </div>

        <div className="flex items-center gap-1.5 text-gray-500 text-sm font-semibold mb-2">
           <MapPin size={16} /> {location}
        </div>
        <h1 className="text-3xl font-black text-gray-800 mb-4">{car.title}</h1>

        {/* Top Badges */}
        <div className="flex flex-wrap items-center gap-3 mb-6">
           <div className="px-3 py-1.5 bg-blue-50 text-blue-700 text-sm font-bold rounded-lg font-mono">Đời xe: {year}</div>
           <div className="px-3 py-1.5 bg-blue-50 text-blue-700 text-sm font-bold rounded-lg font-mono">Odo: {odo}</div>
           <button className="flex items-center gap-1.5 px-3 py-1.5 bg-white border border-gray-200 text-gray-600 text-sm font-bold rounded-lg hover:bg-gray-50">
             <MessageCircle size={16} /> Chat
           </button>
           <button className="flex items-center gap-1.5 px-3 py-1.5 bg-white border border-gray-200 text-gray-600 text-sm font-bold rounded-lg hover:bg-gray-50">
             <Share2 size={16} /> Chia sẻ
           </button>
        </div>

        <div className="flex flex-col lg:flex-row gap-8">
           {/* LEFT COLUMN: Gallery & Info */}
           <div className="lg:w-2/3 flex flex-col gap-6">

              {/* Image Gallery */}
              <div className="bg-white p-2 rounded-2xl shadow-sm border border-gray-100">
                <div className="relative w-full aspect-[16/9] rounded-xl overflow-hidden mb-2 shadow-sm bg-gray-50">
                   <img src={images[activeImage]} alt="Main" className="w-full h-full object-cover" onError={handleImageError} />
                </div>
                <div className="grid grid-cols-4 gap-2">
                  {images.slice(1).map((src, idx) => (
                    <div 
                      key={idx} 
                      className="relative aspect-[4/3] rounded-lg overflow-hidden cursor-pointer border-2 border-transparent hover:border-blue-400 focus-within:border-blue-500 transition-all bg-gray-50"
                      onClick={() => setActiveImage(idx + 1)}
                    >
                       <img src={src} alt={`Thumb ${idx}`} className="w-full h-full object-cover" onError={handleImageError} />
                    </div>
                  ))}
                  {images.length > 5 && (
                    <button className="flex items-center justify-center bg-gray-50 border border-gray-200 rounded-lg text-blue-600 font-bold text-sm hover:bg-blue-50 transition">
                      Xem tất cả ảnh
                    </button>
                  )}
                </div>
              </div>

              {/* Thông tin xe cơ bản */}
              <div className="bg-white rounded-2xl shadow-sm border border-gray-100 overflow-hidden">
                <div className="px-6 py-4 border-b border-gray-100">
                  <h3 className="font-bold text-xl text-gray-800">Thông tin xe cơ bản</h3>
                </div>
                <div className="p-6">
                   <div className="grid grid-cols-2 md:grid-cols-2 gap-y-6 gap-x-8">
                      <div className="flex items-start gap-3">
                         <div className="mt-1 pb-1 pt-1"><Clock className="text-[#0096ff]" size={20} /></div>
                         <div>
                            <p className="text-gray-500 text-sm font-medium">Công tơ mét (ODO)</p>
                            <p className="text-gray-800 font-bold">{odo}</p>
                         </div>
                      </div>
                      <div className="flex items-start gap-3">
                         <div className="mt-1 pb-1 pt-1"><CheckCircle className="text-[#0096ff]" size={20} /></div>
                         <div>
                            <p className="text-gray-500 text-sm font-medium">Năm sản xuất</p>
                            <p className="text-gray-800 font-bold">{year}</p>
                         </div>
                      </div>
                      <div className="flex items-start gap-3">
                         <div className="mt-1 pb-1 pt-1"><CheckCircle className="text-[#0096ff]" size={20} /></div>
                         <div>
                            <p className="text-gray-500 text-sm font-medium">Nhiên liệu</p>
                            <p className="text-gray-800 font-bold">Xăng</p>
                         </div>
                      </div>
                      <div className="flex items-start gap-3">
                         <div className="mt-1 pb-1 pt-1"><CheckCircle className="text-[#0096ff]" size={20} /></div>
                         <div>
                            <p className="text-gray-500 text-sm font-medium">Hộp số</p>
                            <p className="text-gray-800 font-bold">Tự động (AT)</p>
                         </div>
                      </div>
                      <div className="flex items-start gap-3">
                         <div className="mt-1 pb-1 pt-1"><CheckCircle className="text-[#0096ff]" size={20} /></div>
                         <div>
                            <p className="text-gray-500 text-sm font-medium">Kiểu dáng</p>
                            <p className="text-gray-800 font-bold">SUV / Sedan</p>
                         </div>
                      </div>
                      <div className="flex items-start gap-3">
                         <div className="mt-1 pb-1 pt-1"><MapPin className="text-[#0096ff]" size={20} /></div>
                         <div>
                            <p className="text-gray-500 text-sm font-medium">Vị trí</p>
                            <p className="text-gray-800 font-bold">{location}</p>
                         </div>
                      </div>
                   </div>

                   <div className="mt-8 pt-6 border-t border-gray-100">
                     <h4 className="font-bold text-gray-800 mb-3">Tổng quan về {car.title}</h4>
                     <p className="text-gray-600 text-sm leading-relaxed text-justify">
                         {car.userComment || "Xe sở hữu ngoại thất và nội thất hoàn hảo. Trải nghiệm lái xe tuyệt vời kết hợp cùng khối động cơ tiết kiệm nhiên liệu. Phù hợp cho cả gia đình và đi làm hàng ngày."}  
                     </p>
                     <div className="mt-4 flex justify-center">
                        <button className="text-[#0096ff] font-bold text-sm bg-blue-50 px-4 py-1.5 rounded-full hover:bg-blue-100 transition">Xem chi tiết ⌄</button>
                     </div>
                   </div>
                </div>
              </div>
           </div>

            {/* RIGHT COLUMN: Action & Purchase */}
           <div className="lg:w-1/3 flex flex-col gap-5">

              {/* Box 1: Price & Contact */}
              <div className="bg-gradient-to-b from-[#eaf5ff] to-[#f4faff] rounded-2xl p-6 shadow-sm border border-blue-100">
                 <h2 className="text-lg font-bold text-gray-800 mb-4">Thông tin mua xe</h2>

                 <div className="flex justify-between items-center mb-6">
                    <span className="bg-green-500 text-white text-[11px] px-2.5 py-1 font-bold uppercase rounded-full tracking-wider">Đang bán</span>
                    <span className="flex items-center gap-1.5 text-xs font-bold text-gray-600">
                      <Clock size={14} /> Mới đăng
                    </span>
                 </div>

                 <div className="mb-6">
                    <p className="text-gray-500 text-sm font-semibold mb-1">Giá bán</p>
                    <div className="text-4xl sm:text-5xl font-black text-[#0066ff] tracking-tight">{car.highestBid}</div>
                    <p className="text-gray-400 text-xs font-medium mt-1">Giá có thể thỏa thuận</p>
                 </div>

                 <button 
                  onClick={handleContactClick}
                  className="w-full bg-[#0096ff] hover:bg-blue-600 text-white font-bold py-3.5 rounded-xl shadow-[0_4px_15px_rgba(0,150,255,0.3)] transition transform hover:-translate-y-0.5"
                 >
                   Liên hệ mua xe
                 </button>

                 <div className="grid grid-cols-2 gap-4 mt-5">
                    <div className="bg-white p-3 rounded-xl border border-gray-100 flex flex-col justify-center shadow-sm">
                      <div className="flex items-center gap-1.5 text-gray-500 text-xs font-semibold mb-1">
                        <Eye size={14} /> Người xem
                      </div>
                      <div className="font-bold text-lg text-gray-800">125</div>
                    </div>
                    <div className="bg-white p-3 rounded-xl border border-gray-100 flex flex-col justify-center shadow-sm">
                      <div className="flex items-center gap-1.5 text-gray-500 text-xs font-semibold mb-1">
                        <MessageCircle size={14} /> Bình luận
                      </div>
                      <div className="font-bold text-lg text-gray-800">{car.commentsCount || 2}</div>
                    </div>
                 </div>
              </div>

              {/* Box 2: Owner Contact */}
              <div className="bg-white p-5 rounded-2xl shadow-sm border border-gray-100">
                 <div className="flex items-start justify-between">
                    <div>
                       <span className="flex items-center gap-1.5 text-gray-600 text-sm font-bold mb-1">
                         <MessageCircle size={16} className="text-[#0096ff]" /> Thông tin người bán
                       </span>
                       {user ? (
                         <div className="mt-3">
                           <p className="text-gray-800 font-bold text-lg">Đại lý chính hãng</p>
                           <p className="text-[#0096ff] font-bold mt-1 text-xl">0836 304 231</p>
                           <p className="text-gray-500 text-xs mt-2 flex items-center gap-1"><CheckCircle size={12} className="text-green-500"/>Đã xác thực thông tin</p>
                         </div>
                       ) : (
                         <div className="flex items-center gap-2 mt-2">
                            <div className="flex -space-x-2">
                               <div className="w-6 h-6 rounded-full bg-gray-200 border-2 border-white flex items-center justify-center text-[10px] font-bold text-gray-600">A</div>
                               <div className="w-6 h-6 rounded-full bg-blue-200 border-2 border-white flex items-center justify-center text-[10px] font-bold text-blue-800">H</div>
                               <div className="w-6 h-6 rounded-full bg-purple-200 border-2 border-white flex items-center justify-center text-[10px] font-bold text-purple-800">C</div>
                            </div>
                            <span onClick={() => navigate('/login')} className="text-[#0096ff] text-xs font-bold hover:underline cursor-pointer">Đăng nhập để xem thông tin</span>
                         </div>
                       )}
                    </div>
                 </div>
              </div>

              {/* Box 3: Notification Subscribe */}
              {!user ? (
                <div className="bg-blue-50/50 p-5 rounded-2xl shadow-sm border border-blue-100">
                   <div className="flex items-start gap-3">
                     <Phone size={20} className="text-[#0096ff] mt-0.5 shrink-0" />
                     <div>
                        <h4 className="font-bold text-gray-800 text-sm mb-1">Đăng nhập để liên hệ và theo dõi xe</h4>
                        <p className="text-xs text-gray-500 mb-3 leading-relaxed">
                          Lưu xe yêu thích, liên hệ trực tiếp với người bán và nhận thông báo khi có xe mới phù hợp.
                        </p>
                        <Link to="/login" className="inline-block bg-[#0096ff] hover:bg-blue-600 text-white font-bold py-2 px-5 text-sm rounded-lg shadow-sm transition">
                          Đăng nhập miễn phí
                        </Link>
                     </div>
                   </div>
                </div>
              ) : (
                <div className="bg-green-50/50 p-5 rounded-2xl shadow-sm border border-green-100">
                   <div className="flex items-start gap-3">
                     <CheckCircle size={20} className="text-green-500 mt-0.5 shrink-0" />
                     <div>
                        <h4 className="font-bold text-gray-800 text-sm mb-1">Đã đăng ký nhận thông báo</h4>
                        <p className="text-xs text-gray-500 leading-relaxed">
                          Bạn sẽ nhận được thông báo ngay khi có xe tương tự được cập nhật hoặc khi có giá mới!
                        </p>
                     </div>
                   </div>
                </div>
              )}

              {/* Box 4: Comments */}
              <div className="bg-white p-5 rounded-2xl shadow-sm border border-gray-100">
                 <div className="flex items-center justify-between mb-4">
                    <h3 className="font-bold text-gray-800">Hỏi đáp về xe <span className="text-gray-400 font-normal text-sm">({comments.length})</span></h3>
                 </div>

                 <div className="flex gap-2 mb-5">
                    <input
                      type="text"
                      value={commentInput}
                      onChange={e => setCommentInput(e.target.value)}
                      onKeyDown={e => e.key === 'Enter' && handleSendComment()}
                      placeholder="Đặt câu hỏi về xe..."
                      className="flex-1 border border-gray-200 rounded-lg px-3 py-2 text-sm focus:outline-none focus:border-[#0096ff]"
                    />
                    <button
                      onClick={handleSendComment}
                      className="bg-[#0096ff] text-white px-4 py-2 rounded-lg text-sm font-bold hover:bg-blue-600 transition"
                    >
                      Gửi
                    </button>
                 </div>

                 {comments.length === 0 ? (
                   <p className="text-center text-gray-400 text-sm py-4">Chưa có câu hỏi nào. Hãy là người đầu tiên!</p>
                 ) : (
                   <div className="space-y-4">
                     {comments.map((cmt) => (
                       <div key={cmt.id} className="border-b border-gray-50 pb-3 last:border-0">
                          <div className="flex justify-between items-center mb-1">
                             <span className="font-bold text-sm text-gray-800">{cmt.author}</span>
                             <span className="text-[11px] text-gray-400">{cmt.time}</span>
                          </div>
                          <p className="text-gray-600 text-sm leading-relaxed">{cmt.text}</p>
                       </div>
                     ))}
                   </div>
                 )}
              </div>

           </div>
        </div>

      </div>

      {/* Modal Liên Hệ Mua Xe */}
      {showContactModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black bg-opacity-50 px-4">
          <div className="bg-white rounded-2xl shadow-xl w-full max-w-md overflow-hidden animate-fade-in-up">
            <div className="px-6 py-4 border-b border-gray-100 flex justify-between items-center bg-[#f8fbff]">
              <h3 className="font-bold text-lg text-gray-800">Liên hệ mua xe</h3>
              <button 
                onClick={() => setShowContactModal(false)}
                className="text-gray-400 hover:text-red-500 transition"
              >
                ✕
              </button>
            </div>
            <div className="p-6">
              <div className="mb-4">
                <p className="text-sm text-gray-500 mb-1">Xe bạn đang quan tâm:</p>
                <p className="font-bold text-gray-800">{car.title}</p>
                <p className="text-[#0066ff] font-bold text-lg">{car.highestBid}</p>
              </div>
              <div className="space-y-4">
                <div>
                  <label className="block text-sm font-semibold text-gray-700 mb-1">Họ và tên của bạn</label>
                  <input 
                    type="text" 
                    value={user?.name || ''} 
                    disabled
                    className="w-full border border-gray-200 rounded-lg px-4 py-2.5 text-sm bg-gray-50 text-gray-600 focus:outline-none"
                  />
                </div>
                <div>
                  <label className="block text-sm font-semibold text-gray-700 mb-1">Số điện thoại</label>
                  <input 
                    type="text" 
                    value={user?.phone || 'Chưa cập nhật SĐT'} 
                    disabled
                    className="w-full border border-gray-200 rounded-lg px-4 py-2.5 text-sm bg-gray-50 text-gray-600 focus:outline-none"
                  />
                </div>
                <div>
                  <label className="block text-sm font-semibold text-gray-700 mb-1">Lời nhắn (<span className="text-red-500">*</span>)</label>
                  <textarea 
                    rows="3"
                    className="w-full border border-gray-200 rounded-lg px-4 py-2.5 text-sm focus:outline-none focus:border-[#0096ff] focus:ring-1 focus:ring-[#0096ff]"
                    placeholder="Tôi muốn thương lượng giá hoặc xem xe trực tiếp..."
                    value={contactMessage}
                    onChange={(e) => setContactMessage(e.target.value)}
                  ></textarea>
                </div>
              </div>
            </div>
            <div className="px-6 py-4 border-t border-gray-100 flex gap-3">
              <button 
                onClick={() => setShowContactModal(false)}
                className="flex-1 px-4 py-2.5 bg-gray-100 hover:bg-gray-200 text-gray-700 font-bold rounded-xl transition"
              >
                Hủy bỏ
              </button>
              <button 
                onClick={submitContactRequest}
                className="flex-1 px-4 py-2.5 bg-[#0096ff] hover:bg-blue-600 text-white font-bold rounded-xl transition"
              >
                Gửi yêu cầu
              </button>
            </div>
          </div>
        </div>
      )}

      <ChatWidget />
    </div>
  );
};

export default PublicCarDetail;
